rule "cp parse signal"
when
  has_field("message") &&
  contains(to_string($message.message), "signal Internal") &&
  contains(to_string($message.message), "SS:")
then
  let msg = to_string($message.message);
  let modem = regex("signal\\s+Internal\\s+([A-Z0-9]+)", msg);
  set_field("cp_modem", modem["0"]);
  let sim = regex("\\(SIM([0-9]+)\\)", msg);
  set_field("cp_sim", to_long(sim["0"], 0));
  let ss = regex("SS:\\s*([0-9]+)%", msg);
  set_field("cp_signal_strength", to_long(ss["0"], 0));
  let rssi = regex("RSSI:\\s*(-?[0-9.]+)", msg);
  set_field("cp_rssi", to_double(rssi["0"], 0.0));
  let sinr = regex("SINR:\\s*(-?[0-9.]+)", msg);
  set_field("cp_sinr", to_double(sinr["0"], 0.0));
  let rsrp = regex("RSRP:\\s*(-?[0-9.]+)", msg);
  set_field("cp_rsrp", to_double(rsrp["0"], 0.0));
  let rsrq = regex("RSRQ:\\s*(-?[0-9.]+)", msg);
  set_field("cp_rsrq", to_double(rsrq["0"], 0.0));
  let band = regex("RFBAND:\\s*Band\\s+([0-9]+)", msg);
  set_field("cp_rfband", to_long(band["0"], 0));
  let svc = regex("Service:\\s*([A-Za-z0-9]+)", msg);
  set_field("cp_service", svc["0"]);
  set_field("cp_event_type", "signal_report");
end

rule "cp parse client connect"
when
  has_field("message") &&
  contains(to_string($message.message), "client data usage: found new client")
then
  let msg = to_string($message.message);
  let m = regex("ip=([0-9.]+)\\s+mac=([0-9a-f:]+)\\s+\\(([0-9]+)\\s+clients\\)", msg);
  set_field("cp_new_client_ip", m["0"]);
  set_field("cp_new_client_mac", m["1"]);
  set_field("cp_client_count", to_long(m["2"], 0));
  set_field("cp_event_type", "new_client");
end

rule "cp parse gps"
when
  has_field("message") &&
  contains(to_string($message.message), "NCM Location Services")
then
  let msg = to_string($message.message);
  let lat = regex("lat:\\s*(-?[0-9.]+)", msg);
  set_field("cp_gps_lat", to_double(lat["0"], 0.0));
  let lng = regex("lng:\\s*(-?[0-9.]+)", msg);
  set_field("cp_gps_lng", to_double(lng["0"], 0.0));
  let lock = regex("lock:\\s*(True|False)", msg);
  set_field("cp_gps_lock", lock["0"]);
  set_field("cp_event_type", "gps_status");
end

rule "cp parse cell id"
when
  has_field("message") &&
  contains(to_string($message.message), "The cell id for the Internal")
then
  let msg = to_string($message.message);
  let m = regex("port\\s+int[0-9]+\\s+is\\s+(.+)$", msg);
  set_field("cp_cell_id", m["0"]);
  set_field("cp_event_type", "cell_id");
end

rule "cp parse wan dhcp"
when
  has_field("message") &&
  contains(to_string($message.message), "WAN:") &&
  contains(to_string($message.message), "DHCP:") &&
  contains(to_string($message.message), "ipinfo=")
then
  let msg = to_string($message.message);
  let gw = regex("'gateway':\\s*'([0-9.]+)'", msg);
  set_field("cp_wan_gateway", gw["0"]);
  let ip = regex("'ip_address':\\s*'([0-9.]+)'", msg);
  set_field("cp_wan_ip", ip["0"]);
  set_field("cp_event_type", "wan_dhcp");
end
